#include <iostream>
#include <string>

struct QueueNode {
    char data;
    QueueNode* next{nullptr};
    explicit QueueNode(char ch) : data(ch), next(nullptr) {}
};

class CharQueue {
private:
    QueueNode* head{nullptr};
    QueueNode* tail{nullptr};

public:
    CharQueue() = default;
    ~CharQueue() {
        while (head != nullptr) {
            QueueNode* temp = head;
            head = head->next;
            delete temp;
        }
    }

    bool isEmpty() const {
        return head == nullptr;
    }

    void enqueue(char val) {
        auto* newNode = new QueueNode(val);
        if (isEmpty()) {
            head = newNode;
        } else {
            tail->next = newNode;
        }
        tail = newNode;
    }

    void print() const {
        if (isEmpty()) {
            std::cout << "Queue is empty.\n";
            return;
        }
        std::cout << "The queue is:\n";
        for (QueueNode* curr = head; curr != nullptr; curr = curr->next) {
            std::cout << curr->data << " --> ";
        }
        std::cout << "NULL\n";
    }
};

int main() {
    CharQueue q;
    q.enqueue('R');
    q.enqueue('A');
    q.enqueue('D');
    q.enqueue('N');
    q.print();
    return 0;
}

#include <iostream>
#include <optional>

struct Node {
    char data;
    Node* next{nullptr};
    explicit Node(char d) : data(d), next(nullptr) {}
};

class Queue {
private:
    Node* head{nullptr};
    Node* tail{nullptr};

public:
    Queue() = default;
    ~Queue() {
        while (!isEmpty()) {
            dequeue();
        }
    }

    bool isEmpty() const {
        return head == nullptr;
    }

    void enqueue(char val) {
        auto* n = new Node(val);
        if (isEmpty()) {
            head = n;
        } else {
            tail->next = n;
        }
        tail = n;
    }

    std::optional<char> dequeue() {
        if (isEmpty()) {
            return std::nullopt;
        }
        char val = head->data;
        Node* temp = head;
        head = head->next;
        if (head == nullptr) {
            tail = nullptr; // Reset dangling tail pointer
        }
        delete temp;
        return val;
    }
};

int main() {
    Queue q;
    q.enqueue('A');
    q.enqueue('B');

    if (auto res = q.dequeue(); res) {
        std::cout << *res << " has been dequeued.\n";
    }
    if (auto res = q.dequeue(); res) {
        std::cout << *res << " has been dequeued.\n";
    }
    if (auto res = q.dequeue(); !res) {
        std::cout << "Queue is empty.\n";
    }
    return 0;
}
